mapper.select:
SELECT v.*, u.username, a.username AS admin_name FROM volunteer_cert v LEFT JOIN user u ON v.user_id = u.user_id LEFT JOIN user a ON v.audit_admin = a.user_id
AND v.status = #{status}
ORDER BY v.cert_id DESC

mapper.update:
UPDATE volunteer_cert
SET status = #{status},
    audit_admin = #{auditAdmin},
    audit_opinion = #{auditOpinion}
WHERE cert_id = #{certId}
